    perfect: { shape: 'star', c: ['#FFE27A', '#F2B705', '#A87C00'], g: 'M12 3.5l2.6 5.3 5.9.9-4.2 4.1 1 5.8-5.3-2.8-5.3 2.8 1-5.8-4.2-4.1 5.9-.9z' },
    machine: { shape: 'hex', c: ['#9EA6FF', '#4B56C8', '#2A3182'], g: 'M13 3L5 13h6l-1 8 8-10h-6z' },
